import { Component } from '@angular/core';
import { Form, GenericFormComponent } from '../../../shared/generic-form/generic-form.component';
import { ApoyoProveedorService } from '../../../controllers/apoyo.proveedor.service';
import { ApoyoProveedor } from '../../../models/apoyo.proveedor';
import { ActivatedRoute } from '@angular/router';
import { institucionesFinancieras } from '../../../main/creditos/credito-form/form-datos-bancarios/form-datos-bancarios.component';

const FORM_DEF: Form = [
  {
    title: 'Datos Generales',
    fields: [
      {
        key: 'nombre_comercial',
        label: 'Nombre Comercial',
        type: 'text'
      },
      {
        key: 'sucursal',
        label: 'Sucursal',
        type: 'text'
      },
      {
        key: 'direccion',
        label: 'Dirección',
        type: 'text'
      },
      {
        key: 'razon_social',
        label: 'Razón Social',
        type: 'text'
      },
      {
        key: 'rfc',
        label: 'RFC',
        type: 'text'
      },
      {
        key: 'telefono',
        label: 'Teléfono',
        type: 'text'
      },
      {
        key: 'estado',
        label: 'Estado',
        defaultOption: 'NO VERIFICADO',
        options: ['NO VERIFICADO', 'VERIFICADO', 'RECHAZADO', 'POSIBLE FRAUDE']
      },
      {
        key: 'referencia',
        label: 'Referencia',
        type: 'text',
        validator:{
          required:false,
        }
      },
      {
        key: 'nota',
        label: 'Notas o Comentarios',
        type: 'text',
        style: {
          div: 'col-12 col-sm p-3'
        },
        validator: {
          required: false,
        }
      }
    ]
  },
  {
    title: 'Datos Bancarios',
    fields: [
      {
        key: 'banco_nombre',
        label: 'Nombre del Banco',
        options: institucionesFinancieras,
        useAutoComplete: true,
      },
      {
        key: 'cuenta_bancaria',
        label: 'Cuenta Bancaria',
        type: 'number',
        validator: {
          min: 0,
        }
      },
      {
        key: 'clabe_interbancaria',
        label: 'CLABE',
        type: 'text',
        validator: {
          maxLength: 18
        }
      },
    ]
  }
]

@Component({
  selector: 'app-form-proveedor',
  imports: [
    GenericFormComponent,
  ],
  templateUrl: './form-proveedor.component.html',
  styleUrl: './form-proveedor.component.css'
})
export class FormProveedorComponent {
  form = FORM_DEF
  edit?: ApoyoProveedor

  constructor(
    public proveedorController: ApoyoProveedorService,
    private route: ActivatedRoute,
  ) { }

  ngOnInit() {
    this.route.params.subscribe(async (params) => {
      if (params['proveedor_id']) {
        this.edit = await this.proveedorController.find(params['proveedor_id'])
      }
    })
  }
}
